import 'dart:async';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:Rocen/core/master_key_manager.dart';

/// Stage 5 ownership model: MasterKeyManager is an authority/state/lease
/// CONTROLLER. It never holds Master Key bytes. These tests pin down both the
/// preserved Stage 3 control semantics (single provisional, no replacement of
/// established authority, lease-gated acknowledgement) and the new invariant
/// (generated bytes are handed to the caller, never retained; state is
/// operation-scoped and resets when the exclusive operation ends).
void main() {
  setUp(() {
    MasterKeyManager.instance.resetForTesting();
  });

  group('generation hands ownership to the caller', () {
    test('generateProvisionalMasterKeyBytes returns 32 fresh random bytes', () {
      final Uint8List a =
          MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      expect(a.length, MasterKeyManager.masterKeyLengthBytes);
      expect(a.any((b) => b != 0), isTrue);
      expect(MasterKeyManager.instance.state, MasterKeyState.provisional);
      MasterKeyManager.instance.markNoAuthority();

      final Uint8List b =
          MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      expect(b, isNot(equals(a)));
      MasterKeyManager.instance.markNoAuthority();
    });

    test('the manager retains no copy of the returned buffer', () {
      final Uint8List caller =
          MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      final Uint8List snapshot = Uint8List.fromList(caller);
      caller.fillRange(0, caller.length, 0);

      expect(
        () => MasterKeyManager.instance.generateProvisionalMasterKeyBytes(),
        throwsStateError,
      );
      MasterKeyManager.instance.markNoAuthority();
      final Uint8List next =
          MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      expect(next, isNot(equals(snapshot)));
      MasterKeyManager.instance.markNoAuthority();
    });
  });

  group('preserved Stage 3 control semantics', () {
    test('markAuthoritative requires an in-progress provisional operation', () {
      expect(() => MasterKeyManager.instance.markAuthoritative(), throwsStateError);
    });

    test('provisional -> markAuthoritative -> authoritative', () {
      MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      MasterKeyManager.instance.markAuthoritative();
      expect(MasterKeyManager.instance.state, MasterKeyState.authoritative);
    });

    test('cannot generate while authoritative', () {
      MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      MasterKeyManager.instance.markAuthoritative();
      expect(
        () => MasterKeyManager.instance.generateProvisionalMasterKeyBytes(),
        throwsStateError,
      );
    });

    test('markNoAuthority abandons a provisional operation', () {
      MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      MasterKeyManager.instance.markNoAuthority();
      expect(MasterKeyManager.instance.state, MasterKeyState.none);
    });

    test('markNoAuthority refuses to discard established authority', () {
      MasterKeyManager.instance.generateProvisionalMasterKeyBytes();
      MasterKeyManager.instance.markAuthoritative();
      expect(() => MasterKeyManager.instance.markNoAuthority(), throwsStateError);
      expect(MasterKeyManager.instance.state, MasterKeyState.authoritative);
    });
  });

  group('lease-gated acknowledgement', () {
    test('acknowledgeRecoveredAuthority works only inside the active lease',
        () async {
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
        expect(MasterKeyManager.instance.state, MasterKeyState.authoritative);
      });
    });

    test('a stale (released) lease is rejected', () async {
      MasterKeyInitializationLease? captured;
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        captured = lease;
      });
      expect(
        () => MasterKeyManager.instance
            .acknowledgeRecoveredAuthority(lease: captured!),
        throwsStateError,
      );
      expect(MasterKeyManager.instance.state, MasterKeyState.none);
    });

    test('established authority is never silently replaced within one operation',
        () async {
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
        expect(
          () => MasterKeyManager.instance
              .acknowledgeRecoveredAuthority(lease: lease),
          throwsStateError,
        );
      });
    });
  });

  group('operation-scoped state (no lingering authority flag)', () {
    test('state resets to none when the exclusive operation succeeds', () async {
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
      });
      expect(MasterKeyManager.instance.state, MasterKeyState.none);
      expect(MasterKeyManager.instance.isInitializationInFlight, isFalse);
    });

    test('state resets to none when the exclusive operation throws', () async {
      await expectLater(
        MasterKeyManager.instance.runExclusiveInitialization<void>((lease) async {
          MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
          throw StateError('operation failed after acknowledging');
        }),
        throwsStateError,
      );
      expect(MasterKeyManager.instance.state, MasterKeyState.none);
      expect(MasterKeyManager.instance.isInitializationInFlight, isFalse);
    });

    test('a later operation starts clean and may acknowledge again', () async {
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
      });
      await MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) async {
        expect(MasterKeyManager.instance.state, MasterKeyState.none);
        MasterKeyManager.instance.acknowledgeRecoveredAuthority(lease: lease);
      });
      expect(MasterKeyManager.instance.state, MasterKeyState.none);
    });
  });

  group('exclusive initialization serialization', () {
    test('concurrent callers share the single in-flight operation', () async {
      int runs = 0;
      final Completer<void> gate = Completer<void>();
      final Future<int> first = MasterKeyManager.instance
          .runExclusiveInitialization<int>((lease) async {
        runs++;
        await gate.future;
        return 7;
      });
      final Future<int> second = MasterKeyManager.instance
          .runExclusiveInitialization<int>((lease) async {
        runs++;
        return 99;
      });
      gate.complete();
      expect(await first, 7);
      expect(await second, 7);
      expect(runs, 1);
    });

    test('resetForTesting refuses to run while an operation is in flight',
        () async {
      final Completer<void> gate = Completer<void>();
      final Future<void> op = MasterKeyManager.instance
          .runExclusiveInitialization<void>((lease) => gate.future);
      expect(() => MasterKeyManager.instance.resetForTesting(), throwsStateError);
      gate.complete();
      await op;
    });
  });
}
